        const { verification, acceptance } = checks();
        return observe({ verification: { passed: verification.passed, output: verification.output }, acceptance: { passed: acceptance.passed, output: acceptance.output }, changedPaths: [...changed.keys()] });
      }
      return observe({ error: `unknown action ${action?.action}` });
    },
